3	function isAdmin(user) {
4	  if (user.role = 'admin') { return true; }
5	  return false;
6	}
7	
8	function canEdit(user, doc) {
9	  return isAdmin(user) || doc.ownerId === user.id;
10	}
11	
12	module.exports = { isAdmin, canEdit };
