1	// String formatting helpers.
2	
3	function titleCase(s) {
4	  return s.replace(/\b\w/g, c => c.toUpperCase());
5	}
6	
7	function truncate(s, n) {
8	  return s.length <= n ? s : s.slice(0, n - 1) + "…";
9	}
10	
11	module.exports = { titleCase, truncate };
