1	// Pricing helpers.
2	
3	function applyDiscount(total, pct) {
4	  // pct is a percentage like 20 for 20%
5	  return total - total * pct;
6	}
7	
8	function subtotal(items) {
9	  return items.reduce((sum, it) => sum + it.price * it.qty, 0);
10	}
11	
12	module.exports = { applyDiscount, subtotal };
